-- Contenido editorial del proceso confirmado; no inserta pagos, cargos o movimientos.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado) VALUES
('pago-rechazado-reenvio-400','Rechazar un pago y corregir el reporte: $400','Cobranza',
'Rechazo con motivo consultable en el portal, reenvío corregido y validación de un solo ingreso de $400. El reporte original conserva su estado y archivo.',
'Usa un alumno e inscripción vigentes, tutor activo con vínculo financiero vigente, permiso para ver finanzas y cuenta familiar activa. Cuenta bancaria activa del mismo plantel o institucional compatible en MXN. Administrador persistido autorizado para Conceptos, Cuotas, Adeudos, Pagos (incluido validar/rechazar) y Cuentas financieras. No uses el cargo de 500 o850 ya pagados. Las fechas de prueba deben quedar dentro de inscripción/ciclo y ser válidas hoy; adapta el vencimiento 20/10/2026 y corte 07/10/2026 si realizas el ejemplo en otra fecha. Cada etapa explica cómo empezar desde su menú. Selecciona sugerencias de las ayudas, no sólo escribas texto; si hay error de captura, corrígelo y espera el mensaje de guardado. La guía no concede permisos ni ejecuta operaciones.',
'Ejemplo ficticio: cargo RECHAZO-TEST por $400.00, sin beca ni recargos. Primer reporte TEST-RECHAZO-400 se rechaza por comprobante de otro concepto: deuda 400 y cuenta B. Segundo reporte TEST-CORREGIDO-400 se valida: deuda 0, un ingreso 400 y banco B +400, no B +800. Con B=$2,000.00, final=$2,400.00 sin otras operaciones. El propietario confirmó completar la prueba, validación, incremento 400 y comprobante familiar. Las referencias son de prueba: en operación real corregir un comprobante conserva la referencia auténtica de la transferencia y no implica pagar otra vez.',
1,DATE '2026-10-07','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY[
'CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR',
'PAGO_LEER','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='pago-rechazado-reenvio-400';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.* FROM guia_proceso g CROSS JOIN (VALUES
(1,$texto$Preparar el concepto de prueba$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Desde el menú lateral de administración entra a Operación escolar → Cobranza escolar → Conceptos de cobro; pulsa la categoría si está cerrada. 2. En Buscar escribe RECHAZO-TEST y pulsa Aplicar filtros. Si existe el concepto de prueba, pulsa Editar en su fila para comprobarlo; no lo dupliques. 3. Si no existe, pulsa + Nuevo registro y selecciona la institución. Captura Código RECHAZO-TEST, Nombre Prueba de rechazo y reenvío y Categoría Otro. 4. Deja Concepto activo y desmarca Permite beca, Permite descuento y Permite recargo para obtener el importe exacto del ejemplo. 5. Pulsa Crear concepto si es nuevo o Guardar cambios si lo editaste; espera el mensaje de éxito antes de pasar a la cuota.$texto$,$texto$Código RECHAZO-TEST. Concepto de prueba sin beneficios ni recargos; el importe individual se configura en la cuota.$texto$,$texto$Concepto disponible. No existe todavía un ingreso ni un pago recibido.$texto$,$texto$No modifiques conceptos operativos para probar. Reutilizar el concepto no significa reutilizar un cargo que ya liquidaste.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
(2,$texto$Configurar una cuota única de $400$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Cuotas por alumno y pulsa + Nuevo registro. 2. Selecciona institución y plantel; en Inscripción vigente enfoca el buscador, escribe matrícula o nombre si hace falta y selecciona una sugerencia de la inscripción del alumno cuyo tutor tiene acceso familiar. 3. Busca y selecciona el concepto RECHAZO-TEST. Elige Una sola vez, Importe 400.00 y moneda MXN. 4. Captura Fecha límite de pago válida; en el ejemplo 20/10/2026. Abre Configuración adicional y comprueba que la vigencia esté dentro de inscripción/ciclo y comience a más tardar en el corte de generación. 5. Elige Estado Activa y marca Incluir en generación automática de cargos. Pulsa Crear cuota y verifica el mensaje de guardado. 6. Si ya preparaste y pagaste este caso, no vuelvas a crear su cuota para leer la guía. Anota la matrícula y concepto para identificar los registros siguientes.$texto$,$texto$Una cuota por $400.00 MXN, sin beca/recargos. Vencimiento ilustrativo 20/10/2026; adaptar a fechas válidas y vigentes al realizar la prueba.$texto$,$texto$Cuota guardada. Guardar no recibe dinero ni crea por sí mismo un movimiento bancario.$texto$,$texto$No uses Registrar con una fecha diferente: esa opción pertenece al cargo manual, no a esta cuota. No agregues además otro cargo manual que duplicaría el cobro.$texto$,$texto$/admin/catalogos/cuotas-alumno$texto$),
(3,$texto$Generar sólo el adeudo del ejemplo$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos. En la parte superior pulsa Generar automáticos. 2. Selecciona institución, plantel y Fecha de corte institucional actual que alcance el inicio de la cuota; el corte ilustrativo es 07/10/2026. No confirmes una fecha futura. 3. Pulsa Visualizar cuotas por aplicar. En Cuotas que generarán adeudos localiza alumno, concepto RECHAZO-TEST y periodo; comprueba original 400, beca 0 y total $400.00. 4. Pulsa Desmarcar todos y marca únicamente esa fila. Comprueba resumen de selección: 1 registro y $400.00, sin otros alumnos ni otras páginas seleccionadas. 5. Pulsa Confirmar y generar adeudos seleccionados. Espera el resultado. 6. Desde el menú vuelve a Operación escolar → Cobranza escolar → Adeudos de alumnos; escribe matrícula en Buscar, pulsa Aplicar filtros y Ver en la fila RECHAZO-TEST del periodo correcto. Anota su número y verifica saldo $400.00.$texto$,$texto$Original $400.00; ajustes $0.00; pagado acumulado $0.00; saldo pendiente $400.00.$texto$,$texto$Cargo emitido pendiente por $400.00. Todavía no hay ingreso en la cuenta.$texto$,$texto$Visualizar no emite deuda. Si no aparece la cuota, revisa inicio, estado y motivo de exclusión; no generes otros cargos ni borres registros para hacerla aparecer.$texto$,$texto$/admin/cargos/generar$texto$),
(4,$texto$Anotar el saldo de la cuenta receptora$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. 2. En Buscar escribe código o nombre del banco del ejemplo y pulsa Aplicar filtros. Identifica la cuenta activa en MXN disponible para ese plantel, no una caja. 3. Anota Saldo actual de la fila como B; Editar abre el detalle para consultarlo también. No modifiques Saldo inicial. 4. Conserva código/nombre de cuenta y saldo B para comparar después de cada reporte, del rechazo y de la validación final.$texto$,$texto$Si el saldo actual del sistema B es $2,000.00, debe permanecer $2,000.00 después del rechazo y quedar $2,400.00 tras validar el segundo reporte, sin otros movimientos.$texto$,$texto$Referencia bancaria del sistema anotada antes de validar; no se mueve dinero.$texto$,$texto$B es el saldo consultado en Nexo Escolar, no un saldo importado del banco. Otros ingresos/egresos pueden cambiarlo; usa el movimiento vinculado para verificar el ingreso exacto.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
(5,$texto$Enviar el primer reporte para revisión$texto$,$texto$Tutor$texto$,$texto$Portal familiar → Tus pagos$texto$,$texto$1. Abre /familias después de la dirección del sistema (por ejemplo http://localhost:18080/familias). Usa una ventana privada separada si conservas administración e inicia con la cuenta del tutor. 2. En el inicio del portal selecciona el hijo del ejemplo y pulsa Tus pagos. En esa pantalla pulsa Reportar transferencia. 3. En 1 · Selecciona qué vas a pagar enfoca Cargo pendiente del alumno y selecciona sólo el cargo RECHAZO-TEST del número anotado por $400.00. Comprueba alumno, concepto y periodo. 4. Verifica Saldo a pagar 400 y Total a transferir 400 protegidos. En 2 · Selecciona la cuenta destino elige la misma cuenta bancaria anotada en la etapa cuatro. 5. En 3 · Datos de la transferencia captura fecha/hora no futuras y referencia de prueba TEST-RECHAZO-400; en Observaciones indica Prueba controlada de rechazo. 6. En 4 · Adjunta el comprobante pulsa Seleccionar archivos y elige un PDF/JPG/PNG técnicamente válido, legible, identificado como prueba y que corresponda a otro concepto para simular el error de contenido. 7. En 5 · Revisa y envía comprueba el resumen automático y pulsa Enviar transferencia a revisión. Al volver a Tus pagos localiza el primer folio en Tus pagos y comprobantes; anótalo.$texto$,$texto$Primer reporte $400.00, referencia ilustrativa TEST-RECHAZO-400; archivo de prueba con contenido incorrecto, no archivo dañado. Máximo 5 archivos de 10MB.$texto$,$texto$Primer pago En revisión, cargo todavía 400 y cuenta todavía B; no hay ingreso hasta validar.$texto$,$texto$Este paso prueba rechazo administrativo, no aceptación de extensiones o archivos inválidos. No hagas una transferencia real sólo para la prueba. En operación captura los datos auténticos.$texto$,NULL),
(6,$texto$Rechazar con una explicación para el tutor$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Regresa a tu sesión administrativa. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos. 2. En Buscar escribe TEST-RECHAZO-400 o el primer folio anotado, pulsa Aplicar filtros y Ver en su fila; confirma que es el primer reporte por 400 en revisión. 3. Abre Comprobantes y pulsa el enlace del archivo para verlo en otra pestaña. Comprueba por qué no corresponde al cargo; cierra o regresa a la pestaña del pago. 4. Abre Distribución y verifica alumno y cargo de $400.00. Luego abre Gestión. 5. En Rechazar pago captura en Motivo obligatorio: El comprobante corresponde a otro concepto. Adjunta el comprobante correcto del cargo de $400.00. 6. Pulsa Rechazar sin afectar saldos. Comprueba estado Rechazado y que la explicación quedó en el detalle. Conserva el folio; no borres el reporte ni su archivo. 7. Desde el menú entra a Administración → Finanzas → Cuentas financieras, busca la cuenta y pulsa Aplicar filtros: debe seguir en B. En Operación escolar → Cobranza escolar → Adeudos de alumnos busca al alumno, pulsa Aplicar filtros y Ver del cargo anotado: pagado 0 y saldo $400.00.$texto$,$texto$Motivo claro que indica el problema y qué corregir. Primer reporte rechazado por $400.00.$texto$,$texto$Reporte rechazado conservado; sin abono ni ingreso. Cargo $400.00 y cuenta B, salvo otras operaciones independientes.$texto$,$texto$Rechazar no devuelve dinero bancario. Si la transferencia real sí ocurrió, aclara su comprobante/recepción con la familia; no le exijas pagar otra vez para corregir un archivo.$texto$,$texto$/admin/catalogos/pagos$texto$),
(7,$texto$Consultar el motivo y comprobar que puede reenviar$texto$,$texto$Tutor$texto$,$texto$Tus pagos y comprobantes → Ver motivo del rechazo$texto$,$texto$1. Regresa a la ventana del tutor; desde el inicio selecciona el hijo y pulsa Tus pagos. Recarga la pantalla para ver la resolución. 2. Baja a Tus pagos y comprobantes. Si no aparece el primer folio, selecciona Todos los meses y Todos los años, pulsa Buscar pagos y revisa las páginas. 3. Identifica la fila TEST-RECHAZO-400 o su folio, estado Rechazado. Junto al estado pulsa Ver motivo del rechazo. 4. En el modal comprueba folio y Motivo registrado por administración; debe explicar que el comprobante corresponde a otro concepto. Cierra con ×, Escape o clic fuera del cuadro. 5. Comprueba en Lo que falta por pagar que el cargo continúa por $400.00. Pulsa Reportar transferencia y enfoca Cargo pendiente del alumno: el mismo cargo debe poder seleccionarse de nuevo. 6. Si no aparece, no inventes otra deuda: revisa vínculo financiero, saldo, estado, fecha límite y que no haya otro pago en revisión. Si ahora está vencido, administración puede habilitarlo desde Operación escolar → Cobranza escolar → Adeudos de alumnos → Buscar → Aplicar filtros → Ver → Transferencia de cargo vencido con motivo.$texto$,$texto$Mensaje del rechazo visible sin descargar archivos. La deuda sigue $400.00 y el cargo vuelve a estar disponible si cumple elegibilidad.$texto$,$texto$El tutor sabe qué corregir; primer reporte permanece Rechazado. Abrir el modal no modifica el pago.$texto$,$texto$El motivo visible corresponde al pago rechazado de su hijo, no al nuevo reporte. Si falta un motivo histórico, contacta administración. Reenviar el reporte no requiere otra transferencia si el dinero ya salió.$texto$,NULL),
(8,$texto$Enviar un reporte nuevo con el comprobante correcto$texto$,$texto$Tutor$texto$,$texto$Portal familiar → Reportar transferencia$texto$,$texto$1. En la ventana del tutor, desde el inicio entra a seleccionar hijo → Tus pagos → Reportar transferencia; si ya estás en el formulario del paso 7, continúa ahí. 2. En 1 · Selecciona qué vas a pagar selecciona el mismo cargo anotado RECHAZO-TEST por $400.00. No selecciones otro alumno ni agregues otros cargos. 3. Confirma Total a transferir 400; en 2 · Selecciona la cuenta destino elige la cuenta bancaria del ejemplo. 4. En 3 · Datos de la transferencia captura fecha/hora y referencia de prueba TEST-CORREGIDO-400; en Observaciones escribe Reenvío corregido del folio del primer reporte, sustituyendo el texto por su folio real. 5. En 4 · Adjunta el comprobante pulsa Seleccionar archivos y adjunta el archivo correcto de prueba que identifica alumno, concepto y monto $400.00. No reutilices el archivo incorrecto. 6. En 5 · Revisa y envía comprueba alumno, total, cuenta, referencia y archivo. Pulsa Enviar transferencia a revisión. 7. Al volver a Tus pagos busca el folio nuevo en el historial y anótalo. Deben quedar dos reportes: primero Rechazado y segundo En revisión. Cargo todavía 400 y cuenta todavía B.$texto$,$texto$Segundo reporte $400.00 y referencia de prueba TEST-CORREGIDO-400; otro folio, mismo cargo y cuenta.$texto$,$texto$Se conserva el rechazo original y se crea un reporte corregido pendiente, no una modificación del pago anterior.$texto$,$texto$Las referencias TEST son ilustrativas para la prueba. En operación, corregir un archivo no inventa otra referencia bancaria ni exige otra transferencia: conserva los datos auténticos de la misma operación. No envíes un tercer reporte mientras haya uno en revisión.$texto$,NULL),
(9,$texto$Validar sólo el reporte corregido$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Regresa a administración. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos. 2. En Buscar escribe TEST-CORREGIDO-400 o el segundo folio, pulsa Aplicar filtros y Ver en la fila correcta. Confirma En revisión y 400; no abras para validar el primer folio Rechazado. 3. Abre Comprobantes y consulta el archivo corregido en otra pestaña. Revisa referencia, fecha, importe y recepción del dinero en la cuenta destino; en operación real no basta ver la imagen. 4. Abre Distribución y confirma alumno, mismo cargo y 400 solicitados; comprueba saldo actual y que no exista otro abono que cambie la aplicación. 5. Abre Gestión. En Validar o rechazar revisa la cuenta destino precargada; conserva la declarada si es correcta. Cambiar cuenta destino sólo se usa para una corrección real con motivo. 6. Cuando todo esté comprobado pulsa Validar y publicar. Espera la confirmación y comprueba estado Validado del segundo folio. 7. Abre Resumen para identificar el ingreso vinculado y Distribución para verificar abono 400; no registres un movimiento manual adicional ni intentes validar otra vez el primer reporte.$texto$,$texto$Segundo pago validado por $400.00, una aplicación 400 y un ingreso 400. Primer reporte sigue rechazado.$texto$,$texto$Cuenta B + $400.00, cargo liquidado y comprobante oficial del segundo pago disponible.$texto$,$texto$Se valida con usuario administrativo persistido, no recuperación. Sólo se genera un ingreso, nunca $800 por existir dos reportes. Si hubo otras operaciones, verifica el movimiento vinculado.$texto$,$texto$/admin/catalogos/pagos$texto$),
(10,$texto$Comprobar el historial y el comprobante final$texto$,$texto$Administración y tutor$texto$,$texto$Cuentas, adeudos y portal familiar$texto$,$texto$1. Desde el menú lateral administrativo entra a Administración → Finanzas → Cuentas financieras; busca la cuenta del ejemplo y pulsa Aplicar filtros. Verifica Saldo actual B +400, no B +800; consulta movimientos vinculados si hay otras operaciones. 2. Desde el menú entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca al alumno, pulsa Aplicar filtros y Ver del cargo RECHAZO-TEST anotado. Comprueba total 400, pagado acumulado 400 y saldo $0.00. 3. Desde el menú entra a Administración → Finanzas → Pagos recibidos; busca cada folio por separado y pulsa Aplicar filtros: el primero permanece Rechazado y el segundo Validado. 4. Regresa a la ventana del tutor; desde el inicio selecciona el hijo → Tus pagos. Ese cargo ya no debe aparecer entre lo que falta por pagar. 5. En Tus pagos y comprobantes localiza ambos folios, limpiando mes/año y cambiando de página si hace falta. El primero debe conservar Ver motivo del rechazo; el segundo debe ofrecer Ver comprobante PDF. 6. Pulsa Ver comprobante PDF del segundo pago y revisa folio, alumno e importe 400 en la nueva pestaña. La descarga es opcional desde el visor, no automática.$texto$,$texto$Primer reporte rechazado conservado + segundo validado 400 = un solo ingreso 400. Si B=2000, cuenta final 2400; cargo 0.$texto$,$texto$Caso confirmado por el propietario: reenvío validado, cuenta aumentó 400 y comprobante visible en el portal. La guía mantiene todas las comprobaciones para futuras repeticiones controladas.$texto$,$texto$No borres el primer reporte: el rechazo explica el historial. No vuelvas a pagar un cargo liquidado para consultar la guía. Este caso no certifica devoluciones, cancelaciones de pagos validados ni otros métodos.$texto$,$texto$/admin/catalogos/pagos$texto$)
) AS v(numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
WHERE g.slug='pago-rechazado-reenvio-400';
